"""Writes NonogramPictures.kt from the accepted pictures of tools/nonogram/pictures5.txt, pictures.txt and pictures10.txt (see check.py).
Do not edit the output by hand.

Run: python tools/nonogram/gen.py
"""
import os
import sys

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import check  # noqa: E402

OUT = os.path.join(check.HERE, '..', '..', 'shared', 'src', 'commonMain', 'kotlin', 'com', 'mehmtcan', 'brainscroll', 'game', 'nonogram', 'NonogramPictures.kt')

lines = [
    'package com.mehmtcan.brainscroll.game.nonogram',
    '',
    '// Generated by tools/nonogram/gen.py from tools/nonogram/pictures*.txt. Do not edit by hand.',
    '',
]
for size, name in ((5, 'NONOGRAM_PICTURES_5'), (8, 'NONOGRAM_PICTURES_8'), (10, 'NONOGRAM_PICTURES_10')):
    pictures = check.accepted(size)
    ids = [p['id'] for p in pictures]
    assert len(set(ids)) == len(ids), 'duplicate ids in %dx%d' % (size, size)
    names = [p['en'] for p in pictures]
    assert len(set(names)) == len(names), 'duplicate names in %dx%d: %s' % (size, size, [n for n in names if names.count(n) > 1])
    lines.append('/** The accepted %d by %d pictures, in file order (a released picture keeps its place; new ones go at the end of the file). */' % (size, size))
    lines.append('internal val %s: List<NonogramPicture> = listOf(' % name)
    for p in pictures:
        pattern = ''.join(p['rows'])
        lines.append('    NonogramPicture("%s", "%s", "%s", %d, "%s"),' % (p['id'], p['tr'], p['en'], size, pattern))
    lines.append(')')
    lines.append('')
    print('%dx%d: wrote %d pictures' % (size, size, len(pictures)))
with open(OUT, 'w', encoding='utf-8', newline='\n') as f:
    f.write('\n'.join(lines))
